class Solution:
    def findTheDifference(self, s: str, t: str) -> str:
        i = 0
        s = sorted(s)
        t = sorted(t)
        while i < len(s) and i < len(t):
            if s[i] != t[i]:
                return t[i]
            i += 1
        return t[-1]

if __name__ == "__main__":
    solution = Solution()
    print(solution.findTheDifference("abcd", "abcde"))
    print(solution.findTheDifference("", "y"))
    print(solution.findTheDifference("", ""))
